local function CreateCard(parent,title,desc)local c=N("Frame",{Size=UDim2.new(1,-10,0,desc and 62 or 50),BackgroundColor3=Color3.fromRGB(25,12,45),BackgroundTransparency=.5,ZIndex=4},parent)Round(c,8)Stroke(c,PURP,1,.5)N("TextLabel",{Size=UDim2.new(1,-70,0,20),Position=UDim2.fromOffset(12,8),BackgroundTransparency=1,Text=title,Font=Enum.Font.GothamBold,TextSize=14,TextColor3=Color3.new(1,1,1),TextXAlignment=Enum.TextXAlignment.Left,ZIndex=5},c)if desc then N("TextLabel",{Size=UDim2.new(1,-70,0,16),Position=UDim2.fromOffset(12,30),BackgroundTransparency=1,Text=desc,Font=Enum.Font.Gotham,TextSize=11,TextColor3=Color3.fromRGB(160,150,190),TextXAlignment=Enum.TextXAlignment.Left,ZIndex=5},c)end return c end
local function CreateToggle(parent,text,desc,default,cb)local c=CreateCard(parent,text,desc)local on=default or false local tr=N("TextButton",{Size=UDim2.fromOffset(44,22),Position=UDim2.new(1,-56,.5,-11),Text="",AutoButtonColor=false,BackgroundColor3=Color3.fromRGB(40,30,60),ZIndex=5},c)Round(tr,11)local ts=Stroke(tr,PURP,1,.4)local th=N("Frame",{Size=UDim2.fromOffset(16,16),Position=UDim2.fromOffset(3,3),BackgroundColor3=Color3.fromRGB(180,170,200),ZIndex=6},tr)Round(th,8)local glow=Stroke(th,CYAN,2,1)local function set(v,silent)on=v Tw(th,.2,{Position=on and UDim2.fromOffset(25,3)or UDim2.fromOffset(3,3),BackgroundColor3=on and CYAN or Color3.fromRGB(180,170,200)})Tw(tr,.2,{BackgroundColor3=on and Color3.fromRGB(0,90,100)or Color3.fromRGB(40,30,60)})Tw(ts,.2,{Color=on and CYAN or PURP})Tw(glow,.2,{Transparency=on and .2 or 1})if cb and not silent then task.spawn(cb,on)end end tr.MouseButton1Click:Connect(function()set(not on)end)set(on,true)return c,set end
local function CreateSlider(parent,text,min,max,def,cb)local c=CreateCard(parent,text,nil)c.Size=UDim2.new(1,-10,0,62)local val=N("TextLabel",{Size=UDim2.fromOffset(50,20),Position=UDim2.new(1,-62,0,8),BackgroundTransparency=1,Text=tostring(def),Font=Enum.Font.GothamBold,TextSize=13,TextColor3=CYAN,TextXAlignment=Enum.TextXAlignment.Right,ZIndex=5},c)local bar=N("Frame",{Size=UDim2.new(1,-28,0,6),Position=UDim2.new(0,14,0,42),BackgroundColor3=Color3.fromRGB(40,30,60),ZIndex=5},c)Round(bar,3)local fill=N("Frame",{Size=UDim2.fromScale((def-min)/(max-min),1),BackgroundColor3=CYAN,ZIndex=6},bar)Round(fill,3)N("UIGradient",{Color=ColorSequence.new(PURP,CYAN)},fill)local th=N("Frame",{Size=UDim2.fromOffset(16,16),Position=UDim2.new(1,0,.5,0),AnchorPoint=Vector2.new(.5,.5),BackgroundColor3=Color3.new(1,1,1),ZIndex=7},fill)Round(th,8)Stroke(th,CYAN,3,.1)local drag=false local function upd(x)local r=math.clamp((x-bar.AbsolutePosition.X)/bar.AbsoluteSize.X,0,1)local v=math.floor(min+(max-min)*r+.5)fill.Size=UDim2.fromScale(r,1)val.Text=tostring(v)if cb then cb(v)end end bar.InputBegan:Connect(function(i)if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then drag=true upd(i.Position.X)end end)UIS.InputChanged:Connect(function(i)if drag and(i.UserInputType==Enum.UserInputType.MouseMovement or i.UserInputType==Enum.UserInputType.Touch)then upd(i.Position.X)end end)UIS.InputEnded:Connect(function(i)if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then drag=false end end)return c end
local function CreateTab(name,color,icon)local btn=N("TextButton",{Size=UDim2.new(1,0,0,38),BackgroundColor3=Color3.fromRGB(25,12,45),BackgroundTransparency=.5,Text=icon.."  "..name,Font=Enum.Font.GothamMedium,TextSize=13,TextColor3=Color3.fromRGB(180,170,200),AutoButtonColor=false,ZIndex=4},TabList)Round(btn,8)local st=Stroke(btn,color,1,.8)local page=N("ScrollingFrame",{Size=UDim2.new(1,-20,1,-60),Position=UDim2.fromOffset(10,52),BackgroundTransparency=1,BorderSizePixel=0,ScrollBarThickness=3,ScrollBarImageColor3=CYAN,CanvasSize=UDim2.new(),AutomaticCanvasSize=Enum.AutomaticSize.Y,Visible=false,ZIndex=3},Content)N("UIListLayout",{Padding=UDim.new(0,8)},page)N("UIPadding",{PaddingTop=UDim.new(0,2),PaddingRight=UDim.new(0,4)},page)return{btn=btn,st=st,page=page,name=name,color=color}end
